import{_ as t,o,c as d,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"ToDos Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"ToDos Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/todos-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"ToDos Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/todos-overview"}]]},"headers":[],"relativePath":"user-guide/todos-overview.md","filePath":"user-guide/todos-overview.md","lastUpdated":1788108809000}'),a={name:"user-guide/todos-overview.md"};function s(i,e,n,l,c,u){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="todos-module" tabindex="-1">ToDos Module <a class="header-anchor" href="#todos-module" aria-label="Permalink to &quot;ToDos Module&quot;">​</a></h1><p>Personal checklist module on the frozen platform. Separate from <a href="/user-guide/tasks-overview">Tasks</a> (workspace/assignee CRM work). Visibility is <strong>creator-scoped</strong>; the workspace owner can view everyone’s to-dos but cannot edit or delete them.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/todos">todos.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/todos">todos.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/todos">todos.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/leads-overview">leads.md</a> · <a href="/user-guide/tasks-overview">tasks.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-todos">tenant-v1-todos.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Title, description, status, priority, due date</li><li>Statuses: <code>open</code> (UI <strong>To Do</strong>), <code>in_progress</code>, <code>completed</code>, <code>cancelled</code></li><li><strong>Colored tags</strong> — per-workspace ToDos catalog; create/assign inline; filter by <code>tag_id</code></li><li><strong>Personal visibility</strong> — each user only sees to-dos they created</li><li><strong>Workspace owner</strong> (<code>superadmin</code>) can view all to-dos in the workspace</li><li><strong>Creator-only update and delete</strong> — even the owner cannot change or delete someone else’s to-do</li><li><strong>Board (default)</strong> + List (table) view; drag-and-drop auto-saves status</li><li>Module licensing (<code>module:todos</code>) + Spatie permissions</li><li>Audit via <code>PlatformAuditService</code> + Spatie activity log</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>todos.view</code> · <code>create</code> · <code>update</code> · <code>delete</code></p><p>Visibility and delete rules are enforced in policy/service (<code>created_by</code> / owner role), not by omitting delete from staff.</p><h2 id="difference-from-tasks" tabindex="-1">Difference from Tasks <a class="header-anchor" href="#difference-from-tasks" aria-label="Permalink to &quot;Difference from Tasks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tasks</th><th>ToDos</th></tr></thead><tbody><tr><td>Assignee-scoped (<code>tasks.assign</code> → org-wide)</td><td>Creator-scoped (owner role → org-wide view)</td></tr><tr><td>Anyone with <code>tasks.delete</code> can delete</td><td>Only the <strong>creator</strong> can delete</td></tr><tr><td>Assign, notes, digests, KPIs, restore/force</td><td>Slim CRUD + board/list only</td></tr></tbody></table><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Assignment, notes / timeline, due digests, restore / force-delete, KPIs</li><li>Subtasks, recurring to-dos, dependencies</li><li>Calendar views (see <a href="/user-guide/calendar-overview">Calendar</a>)</li><li>Import / export</li><li>Real-time board sync (Reverb / Echo)</li></ul>',13)])])}const h=t(a,[["render",s]]);export{p as __pageData,h as default};
